 const versions='<section class="v12-card"><h2>'+t('试听与版本')+'</h2><div class="v12-media-history">'+assets.map(item=>'<button data-audio-asset="'+esc(item.id)+'" class="'+(asset?.id===item.id?'is-active':'')+'">'+esc(item.filename??item.id)+' · '+(item.selected?t('已选用'):t('候选'))+'</button>').join('')+'</div>'+(asset?'<p class="v12-source">'+esc(asset.source?.description??'')+' · '+(asset.testFixture?'TEST / NOT AI':'')+'</p>'+(asset.url?'<audio class="v12-audio" controls preload="metadata" src="'+esc(asset.url)+'"></audio>':'')+'<p>'+tr('目标时长','Target')+': '+esc(line?.targetDurationUs==null?'—':line.targetDurationUs/1e6)+'s · '+tr('实测时长','Measured')+': '+esc(asset.probe?.durationSeconds??asset.durationSeconds??'—')+'s</p>'+(asset.stale?'<div class="v12-warning">'+t('需复核')+'</div>':'')+'<div class="v12-row">'+button('检查通过','accept-audio')+button('拒绝','reject-audio')+button('选用此版本','select-audio',{disabled:asset.stale||asset.review?.verdict!=='accepted',reason:tr('须先检查当前音频。','Review current audio first.')})+'</div><details><summary>'+t('来源与版本记录')+'</summary><pre>'+esc(JSON.stringify(asset,null,2))+'</pre></details>':empty(tr('尚无音频候选；导入后人工检查，不自动选用。','No audio candidates. Import and review; never auto-select.')))+pager('lineIndex',state.lineIndex,utterances.length,['上一句','下一句'])+button('导入试听','import-audio')+'</section>';
