 const primary=page==='voice'?{label:'保存声音卡',onClick:()=>act('save-voice'),disabled:!state.voice}:page==='editing'?{label:'保存剪辑计划',onClick:()=>act('save-edit'),disabled:!state.edit}:page==='entities'?{label:'继续分镜拆解',href:'/creative.html?stage=storyboard',disabled:!state.creative||state.dirty,reason:tr('请先在人物或场景卡保存未提交的视觉说明。','Save pending visual drafts in their character or scene cards first.')}:page==='prompts'?{label:'编译提示词',onClick:()=>act('compile-prompts'),disabled:!state.project}:page==='general'?{label:'保存',onClick:()=>act('save-preferences')}:page==='storage'?{label:'验证并保存位置',onClick:()=>act('save-directory')}:{label:tr('返回当前项目','Back to project'),href:'/',disabled:!state.project};
 mountStudio(app,{studioPage:page==='video'?'prompts':page,section:page,step:page==='editing'?'export':page==='voice'?'finishing':page==='entities'?'images':page==='prompts'?'video':'script',title:t(title[page]),project:state.project,projects:state.projects,primary,nextText:page==='entities'&&state.dirty?tr('视觉草稿尚未保存。切换对象会保留本页文字；请在对应人物/场景卡点击保存，再进入分镜。','Visual drafts are unsaved. Switching objects preserves text on this page; save each card before continuing.'):tr(page==='voice'?'下一步：检查试听并人工选用，再进入剪辑。':page==='editing'?'下一步：保存计划，再导出MP4或新剪映草稿。':'只保存当前设置与版本；不自动提交生成。',page==='voice'?'Next: review and select audio before editing.':page==='editing'?'Next: save the plan, then export MP4 or a new draft.':'Save settings and revisions without automatically generating.'),beforeAssistantContext:async()=>{if(state.dirty)throw new Error(tr('先保存当前人工修改，再与助手讨论；未保存内容仍保留。','Save current manual edits before discussing with the assistant; unsaved content remains.'));},assistantContextLabel:page==='prompts'||page==='video'?tr('全片提示词说明','Whole-project prompt notes'):undefined,assistantTargetType:page==='entities'?(state.assistantEntityType==='scene'?'scene':'entity'):undefined,assistantTargetId:page==='voice'?lines()[state.lineIndex]?.id:page==='entities'?entityList(state.assistantEntityType)[state[state.assistantEntityType+'Index']]?.id:page==='prompts'||page==='video'?'current':undefined});
 app.querySelector('[data-field="connection-model"]')?.setAttribute('list','service-models');if(state.services?.connections?.[state.connectionIndex]?.provider==='chatgpt-siwc')app.querySelector('[data-field="connection-secret"]')?.closest('label')?.setAttribute('hidden','');translateInterface(app); for(const editor of app.querySelectorAll('.v12-line-text,.v12-performance-label textarea')){if(editor.scrollHeight>editor.clientHeight+1)editor.style.height=(editor.scrollHeight+2)+'px';}
