async function refresh(){
 const requests={services:'/api/services'+(state.project?'?projectId='+state.project.id:''),preferences:'/api/studio/preferences',storage:'/api/studio/storage',knowledge:'/api/creative/knowledge'};
 if(state.project)Object.assign(requests,{creative:projectBase()+'/creative',images:projectBase()+'/images',visual:projectBase()+'/visuals',prompts:projectBase()+'/studio-prompts',voice:projectBase()+'/voice',edit:projectBase()+'/edit-plan',mediaTasks:projectBase()+'/service-tasks'});
 const results=await Promise.allSettled(Object.values(requests).map(url=>api(url)));const warnings=[];
 Object.keys(requests).forEach((key,index)=>{if(results[index].status==='fulfilled')state[key]=results[index].value;else if(({services:'services',general:'preferences',storage:'storage',directors:'knowledge',style:'visual',entities:'visual',prompts:'prompts',voice:'voice',editing:'edit'})[page]===key)warnings.push(results[index].reason.message);});
 state.error=warnings.join(' · ');state.dirty=false;
 if(state.preferences){preferences({language:state.preferences.language?.startsWith('en')?'en':'zh',theme:state.preferences.theme});}
 render();
}
